// ── Send a turn ────────────────────────────────────────────
export function ensureApp(chat, exceptMid, pair) {
	// THE ENGINE RUNS THE TURN'S MODEL (D-20261018-09 U1d): `pair`, the daimon half of the set the
	// turn resolved at its start, or, for a caller outside a turn, the model in force now. A chat
	// that follows the default stores no model and is never written one here, so an engine built
	// on another pair is rebuilt at the next turn's start (never under a running turn).
	var want = pair || turnModelOf(chat);
	// A runner's turn settled while this engine was busy (`staleEngine`): it goes at the first
	// build after, before anything reconciles it, and is laid again from the stored session.
	if (chat._engineStale && chat.app && !chat._generating && !chat.app.busy) staleEngine(chat);
	if (chat.app) {
		var held = chat._appPair;
		if (!held || chat._generating
			|| (held.model === (want.model || '') && held.provider === (want.provider || ''))) {
			// The routing rows change the stored routing between turns (U5b), and an engine
			// that is kept would otherwise send what it was built with until the next reload.
			if (held && !chat._generating) applyProviderRouting(chat.app, held.provider, held.model);
			return reconcileEngine(chat, exceptMid);
		}
		diag('chat engine', 'chat=' + String(chat.id || '').slice(0, 12) + ' model ' + held.model + ' -> ' + (want.model || '') + ', rebuilt');
		keepChatTaint(chat, chat.app);	// the old engine's verdict, before it goes (H3)
		chat.app = null; chat._held = null;
	}
	var a = appCfgFor(want);
	// A DaimondApp's key is fixed at construction, so record WHICH minted key it froze. A
	// chat built before somebody else re-minted holds a revoked key and will 401 on its next
	// turn; the generation is how the retry tells that apart from a key that is genuinely
	// spent, and takes the live key instead of buying another. Not persisted: `slimChat`
	// keeps a whitelist, and this belongs to the app object, which does not survive a reload.
	chat._gen = creditsGen();
	// `_capTry` is set only while a turn is mid-backoff, after a provider
	// refused the length first asked for; it lasts exactly as long as that
	// retry and is not persisted.
	// The account's steering notes for this model, composed into the chat's prompt (an ordinary
	// chat has no Diamond, so no Diamond's). Remembered so a change of notes rebuilds it.
	chat._steer = (typeof Notes === 'object' && Notes) ? Notes.steerFor(a.model, chat.diamondId || '') : '';
	var chatSys = Instructions.compose(SYSTEM_PROMPT(a.model, chat._steer), '');
	chat.app = new DaimondApp(a.baseUrl, a.apiKey, a.model,
		chat._capTry || maxOutFor(a.model, a.provider),
		chatSys, pg.cfg.tools !== false);
	// The user's own chat may send workers out; a worker may not. `Tool::browser`
	// in src/tools.rs is the list BOTH are built from, so the dispatch tool is not
	// in it and is added here, by the one caller that builds a chat. A worker that
	// could dispatch workers is a fan-out with no bottom.
	//
	// Guarded on the call existing so an older engine simply does not offer it,
	// rather than throwing and leaving the user with no chat at all.
	if (pg.cfg.tools !== false && typeof chat.app.allow_dispatch === 'function') {
		chat.app.allow_dispatch();
	}
	// WHAT THE CONVERSATION HAS READ, before it runs anything (H3 TAINT-DURABLE): the record's
	// one-way stamp, so a reload, a model switch or an edit-and-resend's rebuild starts tainted.
	applyChatTaint(chat, chat.app);
	// What this engine was built on, beside it and NOT on the record (U1d): the record keeps only a
	// deliberate pick, and writing the resolved pair back made every following chat a pinned one.
	// Not persisted (`slimChat` keeps a whitelist): an engine does not survive a reload either.
	var ap = { provider: a.provider || want.provider || '', model: a.model || '' };
	chat._appPair = ap;
	// The fingerprint is of the very text the app was built with, which for a chat is the
	// role and the standing instructions and nothing else.
	noteAppProv(chat.app, 'chat', ap.model, ap.provider, promptPrint(chatSys), '');
	// A chat freezing its model is a use of it. Recorded here rather than in the
	// pulldown, because a model picked and never run is not one anybody uses.
	try { DaimondModels.noteUse(ap.provider, ap.model); } catch (e) { /* never block a turn */ }
	// How big this model's window is, so a long chat is folded before the provider
	// refuses it rather than after. `contextWindow` returns null for a model nobody
	// publishes a figure for, and a null is left alone: the agent's own default
	// assumption is a better guess than a number invented here, and the reactive
	// fold still catches a refusal either way.
	try {
		var cw = window.DaimondPricing
			? DaimondPricing.contextWindow(ap.model, ap.provider)
			: null;
		if (cw && chat.app.set_context_window) chat.app.set_context_window(cw);
	} catch (e) { /* an older wasm build has no setter */ }
	applyRoundLimit(chat.app);
	applyLiveness(chat.app);
	applyFoldSettings(chat.app, ap.provider);
	applyProviderRouting(chat.app, ap.provider, ap.model);
	applySight(chat.app, ap.provider, ap.model);
	applyEffort(chat.app, ap.provider, ap.model, chat.effort || '');
	applyCrystalCap(chat.app);
	// THE STANDING NETWORK ANSWER, applied before this chat has run anything.
	// `net_consent` lives on the engine and a new engine starts with none, so
	// every new chat -- and every chat after a reload, since these objects do not
	// survive one -- put the question again from scratch. A person who had
	// answered it in one chat was asked in the next and called it, correctly, not
	// having got rid of anything.
	try {
		var st = window.DaimondHandMode ? DaimondHandMode.standingNet() : '';
		if (st && chat.app.set_net_answer) chat.app.set_net_answer(st);
	} catch (e) { /* an older engine has no setter; it simply asks */ }
	// A LOUD ARM LEAVES NOTHING HALF-BUILT (check_l L-R2). Kept, `chat.app` with no `_held`
	// sent the next send to `reconcileEngine`, which returns on no record, onto an empty
	// engine. Dropped, every send rebuilds and stays loud until the fault is gone.
	try { armEngine(chat, exceptMid); }
	catch (e) { chat.app = null; chat._held = null; throw e; }
	return chat.app;
}

/// Lay a chat's conversation into its engine, and answer the mids the engine now holds: every prose message of the chat
/// but `exceptMid`. Seeds the model's own stored session (it carries the provider's tool-call ids, and is the folded list
/// once compaction has run) with the prose after it, else the prose alone.
///
/// # Arguments
/// * `prose` - Seed from the transcript alone, in the chat's order, and not from the stored session, whose order is the
///   order one engine heard the turns in (see `reconcileEngine`).
function seedEngine(chat, exceptMid, prose) {
	// A rebuilt DaimondApp starts with an empty Session, so a chat reopened
	// after a reload would send only its newest message and the model
	// would answer with no memory of the conversation on screen. Seed
	// the persisted history back in, with the token counters, so the
	// first turn after a reload is also metered against the real total.
	var hist = (chat.messages || []).filter(function (msg) {
		// `exceptMid` drops the one message a peer turn is about to RE-SEND through
		// `run_turn` (the dispatched prompt), so it is not seeded into the agent as
		// well and fed to the model twice (D3). Absent, every caller keeps the whole
		// history unchanged.
		if (exceptMid && msg && String(msg.mid) === String(exceptMid)) return false;
		return msg && msg.content && (msg.role === 'user' || msg.role === 'assistant');
	});
	// The model's OWN conversation first, when one was stored. It is a different
	// thing from the transcript on screen: it carries the provider's tool-call ids,
	// so what the agent read, wrote and ran comes back with it — and it is the
	// FOLDED list when compaction has run, so a reloaded chat does not spring back
	// to the full size the screen still shows.
	var sess = prose ? null : chat.session, seeded = 0, laid = false;
	// The prompt copies a hand-off before 5.1 stored, taken out before the model sees
	// them again; the session is stored clean at this turn's end (`dedupeSession`).
	if (sess && Array.isArray(sess.msgs)) {
		var clean = dedupeSession(sess.msgs, chat.messages, sess.upto, sess.uptoTs);
		if (clean !== sess.msgs) {
			diag('session duplicates dropped', 'chat=' + String(chat.id || '').slice(0, 12) + ' '
				+ (sess.msgs.length - clean.length) + ' of ' + sess.msgs.length);
			sess = chat.session = Object.assign({}, sess, { msgs: clean, marks: {} });	// the places moved
		}
	}
	// Turns another tab took after this session was stored, as `tailAfter` finds them. One laid on by id whose prompt
	// stands before a prompt the session holds would be read after that later turn (check_fix5 L1): the model's
	// history cannot be inserted into, so the engine is laid from the transcript instead, as `sessionPlan` does for
	// `order`.
	var tail = [];
	if (sess && sess.msgs && sess.msgs.length) {
		tail = tailAfter(chat, sess);
		var doubt = sessionDoubt(chat, sess, tail, exceptMid);
		var early = doubt === 'early', lost = doubt === 'lost', lacks = doubt === 'lacks';
		if (early || lost || lacks) {
			diag('session out of order', 'chat=' + String(chat.id || '').slice(0, 12) + (early
				? ' a turn it never heard stands before one it holds'
				: lacks ? ' a runner\'s answer it never took stands before its marker'
				: ' an untagged answer follows a turn laid on by id') + '; the engine is laid from the transcript');
			sess = null;
		}
	}
	if (sess && sess.msgs && sess.msgs.length && chat.app.restore_session) {
		try {
			seeded = chat.app.restore_session(sess.msgs,
				chat.promptTokens || 0, chat.completionTokens || 0, chat.lastPrompt || 0,
				chat.cachedTokens || 0, chat.costUsd || 0);
		} catch (e) { seeded = 0; }
	}
	if (seeded) {
		// Turns another tab took after this session was stored. Prose only — that is
		// all a screen transcript holds — appended behind the part that carries ids.
		//
		// LESS THE MESSAGE ABOUT TO BE RE-SENT (F3, 2026-09-25). `exceptMid` filtered
		// only the path above, and a chat that had run a turn stores a session, so every
		// handed-off turn after a chat's first appended its own prompt here and then
		// sent it again through `run_turn`: the model read it twice, and
		// `captureSession` kept the copy for every later request in the chat.
		if (chat.app.append_message) {
			tail.forEach(function (m) {
				if (exceptMid && String(m.mid) === String(exceptMid)) return;
				try {
					// An interjection was said into a turn, never run as one (B3).
					chat.app.append_message(m.role, m.content || '',
						(m.role === 'user' && typeof m.pre === 'string' && m.pre) ? m.pre : undefined,
						(m.role === 'user' && m.mid) ? String(m.mid) : undefined,
						m.role === 'user' && !m.interject);
				} catch (e) { /* skip one */ }
			});
		}
	} else if (hist.length) {
		// No usable session: the old path, which is also the path a chat written by
		// an earlier build takes, and the one a backup from before this store took.
		// It throws while a turn holds the session (check_last), before it touches it: the
		// engine keeps what it held, so the failure is the caller's, not an empty engine
		// whose record would have the next reconcile append the whole chat (check_f1stop P3).
		try {
			chat.app.restore(hist, chat.promptTokens || 0, chat.completionTokens || 0, chat.lastPrompt || 0,
				chat.cachedTokens || 0, chat.costUsd || 0);
			laid = true;
		} catch (e) {
			diag('engine restore failed', 'chat=' + String(chat.id || '').slice(0, 12) + ' ' + String(e && e.message || e).slice(0, 80));
			// Marked as the restore's own, so `armEngine` forgives this and nothing else.
			var re = new Error('engine restore failed: ' + String(e && e.message || e));
			re.restore = true; re.cause = e;
			throw re;
		}
	}
	if (seeded || laid) {
		// The wasm counters now hold the restored totals, so meter the
		// next turn against those rather than against zero. All four, not
		// two: a cost counter restored to the session total while its `prev`
		// stayed at zero would bill the whole reloaded conversation again as
		// the first turn after the reload.
		chat.prevPrompt     = chat.promptTokens || 0;
		chat.prevCompletion = chat.completionTokens || 0;
		chat.prevCached     = chat.cachedTokens || 0;
		chat.prevCost       = chat.costUsd || 0;
	}
	var held = {};
	if (seeded || laid) hist.forEach(function (m) { held[String(m.mid)] = 1; });
	return held;
}

/// Record what a freshly built engine was given, so that a later turn can tell what it lacks. Kept on the chat and not
/// persisted: it is a fact about the engine object, which does not survive a reload.
function armEngine(chat, exceptMid) {
	var mids = {};
	// A fresh engine whose restore failed holds nothing, and its record says so. Any
	// other throw is a fault in the seeding itself and leaves `ensureApp` loud.
	try { mids = seedEngine(chat, exceptMid, false); }
	catch (e) { if (!(e && e.restore === true)) throw e; mids = {}; }
	chat._held = { app: chat.app, mids: mids, ran: false };
}

/// What a live engine lacks of its chat, and what to do about it. Pure: the mids the engine holds, whether it has run a
/// turn, the chat's messages in their converged order and the one message a turn is about to send again.
///
/// * `none`   - nothing is missing.
/// * `seed`   - something is missing and the engine has run nothing: lay the chat in again, as a build does.
/// * `append` - everything missing falls after the last message the engine holds: add it behind.
/// * `order`  - something missing falls BEFORE the last message the engine holds (two devices sent at once): the
///   model's history cannot be inserted into, so it is laid again from the transcript, which is in the chat's order.
///
/// A partial or streamed copy of an answer is not missing yet: the whole copy replaces it under the same mid. A framed
/// copy (a runner's final frame) is missing once its turn's placeholder has gone, since none replaces it then.
function sessionPlan(held, ran, msgs, exceptMid) {
	var ex = exceptMid ? String(exceptMid) : '', tail = -1, first = -1, add = [];
	var unsettled = {};		// the turns whose hand-off still stands (an empty dispatched placeholder)
	(msgs || []).forEach(function (m) {
		if (m && m.why === 'dispatched' && m.iturn && !(m.content && m.content.trim())) unsettled[String(m.iturn)] = 1;
	});
	for (var i = 0; i < (msgs || []).length; i++) {
		var m = msgs[i];
		if (!m || !m.content || (m.role !== 'user' && m.role !== 'assistant')) continue;
		var id = String(m.mid);
		if (ex && id === ex) continue;
		if (held[id] === 1) { tail = i; continue; }
		if (m.role === 'assistant' && (m.interrupted || m.provisional)) continue;
		// A FRAMED ROW IS THE ANSWER once its turn has settled (QA ccp1 H1): no runner parcel replaces a
		// Kimberlite runner's final frame, so a framed row whose placeholder is gone is laid as any answer.
		if (m.role === 'assistant' && m.framed && unsettled[String(m.iturn || '')] === 1) continue;
		if (first < 0) first = i;
		add.push(m);
	}
	if (!add.length) return { act: 'none', add: add };
	if (!ran) return { act: 'seed', add: add };
	return { act: first < tail ? 'order' : 'append', add: add };
}

/// THE ENGINE'S SESSION IS A FUNCTION OF THE CHAT, brought up to it where every turn passes, and not only when the
/// engine is built (D-20261002-08). An engine is a cache of the chat: a turn that reaches the chat by sync, by another
/// tab, or by the transcript loading after the engine was built, never reached the model, and the session a turn then
/// stored made the loss permanent.
///
/// An engine that has run no turn is laid in again IN PLACE, and not rebuilt: the permissions chip and `markRead` set
/// consent and taint on the idle engine, and those live on the engine, not in its session. One that has run turns takes
/// `append_message` for each prose message it does not hold, with `pre` as the record holds it (as the sending device's
/// model read it). Where a message it lacks falls before its last one (concurrent turns) it is laid in again from the
/// transcript, in place for the same reason, so the model's history is the chat's order on every device. That drops the
/// tool-call ids of the earlier turns and unfolds a folded session, as a restored backup does; it is the price of order.
///
/// Not while the engine is busy (`app.busy`: a turn or a fold running or sent, or a steer child): the engine refuses a
/// session write then. The next turn start is the next chance. An engine this chat did not build (a daimon's client) is
/// not touched.
function reconcileEngine(chat, exceptMid) {
	var app = chat.app, h = chat._held;
	if (!h || h.app !== app || chat._generating) return app;
	if (app.busy) return app;
	var plan = sessionPlan(h.mids, h.ran, chat.messages, exceptMid);
	if (plan.act === 'none') return app;
	try {
		if (plan.act === 'append' && typeof app.append_message === 'function') {
			plan.add.forEach(function (m) {
				app.append_message(m.role, m.content || '',
					(m.role === 'user' && typeof m.pre === 'string' && m.pre) ? m.pre : undefined,
					(m.role === 'user' && m.mid) ? String(m.mid) : undefined,
					m.role === 'user' && !m.interject);		// an interjection opens no turn (B3)
				h.mids[String(m.mid)] = 1;
			});
			return app;
		}
		// An idle engine keeps the stored session where the missing messages all follow its marker; where one
		// falls before it, the marker would lose it again and the chat's order is laid from the prose.
		var prose = plan.act === 'order';
		if (!prose && chat.session) {
			var tail = {};
			tailAfter(chat, chat.session).forEach(function (m) { tail[String(m.mid)] = 1; });
			prose = plan.add.some(function (m) { return tail[String(m.mid)] !== 1; });
		}
		h.mids = seedEngine(chat, exceptMid, prose);
	} catch (e) {
		diag('engine reconcile failed', 'chat=' + String(chat.id || '').slice(0, 12) + ' ' + String(e && e.message || e).slice(0, 80));
	}
	return app;
}

/// A turn is about to give `app` the message `mid`: it has run one, and holds that message.
export function heldRun(chat, app, mid) {
	var h = chat._held;
	if (!h || h.app !== app) return;
	h.ran = true;
	if (mid) h.mids[String(mid)] = 1;
}

/// `app` holds the message `mid` by a door other than the seed: a finished answer, a correction that landed.
export function heldNote(chat, app, mid) {
	var h = chat._held;
	if (h && h.app === app && mid) h.mids[String(mid)] = 1;
}

/// Store the conversation the MODEL holds for `chat`, as its agent now has it.
///
/// Called at the end of every turn, win or lose. What it saves is not the transcript
/// on screen: it is the agent's own message list, which carries the provider's
/// tool-call ids — the thing the browser cannot mint, because it never sees them —
/// and which compaction has already folded if the conversation outgrew the window.
///
/// `upto` marks the last screen message the stored list accounts for, so a turn
/// another tab took meanwhile can be appended on the next restore rather than lost
/// or, worse, added twice.
///
/// `back` is a runner's session sent home (KT-5, `settleRunnerSession`), `{msgs, upto,
/// uptoTs}`: stored in place of this engine's, its marker the runner's final frame row, by
/// the same path, so a turn run there is kept as one run here is. `app` is then null.
export function captureSession(chat, app, back) {
	// The engine's taint verdict onto the record FIRST, before anything below can return (H3):
	// every turn's end passes through here, and the engine is the only copy until it does.
	keepChatTaint(chat, app);
	if (!chat) return;
	if (!back && (!app || !app.export_session)) return;
	try {
		var msgs = back ? back.msgs : app.export_session();
		if (!msgs || !msgs.length) return;
		var all  = chat.messages || [];
		// THE MARKER MUST STAND ON A MESSAGE THE AGENT ACTUALLY HOLDS.
		//
		// A turn that died leaves an INTERRUPTED assistant message in the transcript,
		// pushed before this runs -- and the engine's own list stops at the prompt,
		// because `run_turn` threw before any reply was appended to it. Marking the
		// partial as accounted for made the stored session lie: `tailAfter` found
		// nothing left to append, so a Continue rebuilt the conversation WITHOUT the
		// words the model was being asked to carry on from, and the model started
		// again. The request went out and the answer was a fresh one -- the exact
		// complaint `continueTurn` was written to end, one layer further down.
		//
		// Trailing furniture is walked past for the same reason: an `end_log` or an
		// `error_log` is not a message the agent holds, and a marker standing on one
		// leaves `tailAfter` with nothing after it to find.
		//
		// And a row that reached the transcript from outside this engine is not one it holds: a runner's
		// streamed row, or its final frame that landed while a turn ran here (QA ccp1 M1). The marker
		// stands on the last row the engine holds.
		var holds = back ? null : engineHolds(chat, app);
		var last = back ? { mid: String(back.upto || ''), ts: Number(back.uptoTs) || 0 } : sessionMarker(all, holds);
		var list = Array.prototype.slice.call(msgs);
		// WHERE EACH TURN STARTS in the list, by its prompt's mid, so a retracted turn can
		// be cut out at its own prompt and the turns before it keep their tool-call ids and
		// the fold (`sessionCut`). The engine's user entries carry the row they were said as
		// (`run_turn` and `append_message` take its mid), and the marks are read from those
		// and NEVER from the words: two queued turns that both say "continue" paired by text
		// filed the running turn's place under the queued one (check_fix3 F1). A folded turn,
		// an entry from an older build and a turn this engine never heard carry no mid here,
		// so they get no mark. A prompt held twice is marked at its first copy.
		var marks = {};
		for (var j = 0; j < list.length; j++) {
			var e = list[j];
			if (e && e.role === 'user' && e.mid && marks[String(e.mid)] === undefined) marks[String(e.mid)] = j;
		}
		chat.session = {
			v:      1,
			msgs:   list,
			upto:   last ? (last.mid || '') : '',
			uptoTs: last ? (last.ts  || 0)  : 0,
			marks:  marks,
			held:   sessionHeld(all, last, list, holds),
		};
	} catch (e) { /* the chat is fine without it; the next turn writes another */ }
}

/// The mids of the transcript rows at or above marker `last` that the stored list `list` holds,
/// as a set (QA ccp2 M2). A row above the marker that is not in it is one the engine never took:
/// a runner's answer still streaming at the capture and framed after it, or one that synced in
/// above the marker later, and `tailAfter` lays it. With `holds` (`engineHolds`), a row counts
/// only where the engine holds it and holds its turn's prompt, by the id rule of `tailAfter`; a
/// runner's session sent home (no `holds`) holds every row up to its marker but the streamed.
function sessionHeld(all, last, list, holds) {
	var held = {};
	if (!last) return held;
	var end = all.indexOf(last);
	if (end < 0) {
		for (var b = all.length - 1; b >= 0; b--) if (all[b] && last.mid && all[b].mid === last.mid) { end = b; break; }
	}
	var heard = {}, first = '', whole = true;
	for (var j = 0; j < list.length; j++) {
		var x = list[j];
		if (!x || x.role !== 'user') continue;
		if (x.mid) { heard[String(x.mid)] = 1; if (!first) first = String(x.mid); }
		else if (first) { whole = false; break; }
	}
	// The id rule from the first prompt the list holds by id on, as `tailAfter` reads it: before it, a
	// folded or unmarked turn cannot be told from an unheard one, so the marker alone decides.
	var firstAt = -1;
	if (first && whole) for (var k = 0; k < all.length; k++) if (all[k] && all[k].role === 'user' && String(all[k].mid || '') === first) { firstAt = k; break; }
	for (var a = 0; a < all.length; a++) {
		var r = all[a];
		if (!r || !r.mid || !r.content || (r.role !== 'user' && r.role !== 'assistant') || r.provisional) continue;
		if (end >= 0 ? a > end : (r.ts || 0) > (last.ts || 0)) continue;
		if (holds && !holds(r)) continue;
		var turn = r.role === 'user' ? String(r.mid) : String(r.iturn || '');
		if (firstAt >= 0 && a > firstAt && turn && heard[turn] !== 1) continue;
		held[String(r.mid)] = 1;
	}
	return held;
}

/// THE CONVERSATION COMES HOME (KT-5): a runner's settling `report` carries its engine's
/// session after the turn, with the runner's tool calls and folds, and it is stored as the
/// chat's (or the Diamond's) session through `captureSession`, so the next turn here goes on
/// from it as if the turn had run here. No merge, and nothing stored where it would be wrong:
///
/// * `busy`   - a turn runs here in the same chat: its own capture would overwrite the runner's.
/// * `stayed` - the session stayed on the runner (over the post door).
/// * `moved`  - the session here moved meanwhile (its `upto` is not the `base` the errand carried).
/// * `cut`    - the turn was retracted here (its prompt or its answer is tombstoned): a report heard
///   again must not put it back (QA ccp1 M2). Keyed on the turn by the tombstones every retraction
///   writes, so it holds across a reload and grows nothing of its own.
///
/// Whatever stores nothing leaves the chat's engine stale (`staleEngine`): it holds the
/// conversation from before the turn, and the runner's answer is a `framed` row no parcel
/// replaces, so it is rebuilt from the stored session and the transcript (QA ccp1 H1). The
/// diagnostics say which. Answers 'stored', 'busy', 'stayed', 'moved', 'cut', 'words' or ''.
///
/// * `words`  - the words the run's folds staged were not filed here (`settleRunnerWords`
///   answered `filed` false): the session folded them away, so only the transcript, which
///   still holds every one, may lay the next engine (U2).
export function settleRunnerSession(report, filed) {
	if (!report || !window.DaimondPeer || !window.DaimondPeer.settlingReport(report)) return '';
	var chat = chatHoldingTurn(report.turnId);
	if (!chat) return '';
	var said = 'chat=' + String(chat.id || '').slice(0, 12) + ' turn=' + String(report.turnId || '');
	var s = report.session;
	var whole = !!(s && typeof s === 'object' && Array.isArray(s.msgs) && s.msgs.length);
	var held = (chat.session && chat.session.msgs && chat.session.msgs.length) ? String(chat.session.upto || '') : '';
	// The same report heard again (a re-collect) finds its own session already stored.
	if (whole && held && held === String(s.upto || '')) return 'stored';
	var out = '', why = '';
	var tombs = loadMsgTombs();
	if (filed === false) {
		out = 'words'; why = 'his words the run staged were not filed here';
	} else if (chat._generating || (chat.app && chat.app.busy)) {
		out = 'busy'; why = 'a turn runs here in this chat, and its own capture would overwrite it';
	} else if (tombs[String(report.turnId || '')] || (whole && tombs[String(s.upto || '')])) {
		out = 'cut'; why = 'the turn was retracted here';
	} else if (report.sessionStayed) {
		out = 'stayed'; why = 'it stayed on the runner (over the post door)';
	} else if (!whole) {
		out = ''; why = 'the report carries none';
	} else if (held !== String(s.base || '')) {
		out = 'moved'; why = 'the session here moved meanwhile (' + held + ', the runner began at ' + String(s.base || '') + ')';
	}
	if (out || why) {
		diag('runner session', said + ' not stored: ' + why + '; the next turn lays its engine from the transcript');
		staleEngine(chat);
		return out;
	}
	captureSession(chat, null, { msgs: s.msgs, upto: s.upto, uptoTs: s.uptoTs });
	// A chat's engine holds the conversation from before the turn: dropped, so the next Here
	// turn is laid from the session just stored. A Diamond's daimon is laid from it per turn.
	staleEngine(chat);
	touchChat(chat);
	persistChats();
	return 'stored';
}

/// HIS WORDS COME HOME (U2): a runner's folds filed nothing on its own disk; what they staged over
/// the words log this tab seeded rides the `report` as `words`, in the log's entry form, and is
/// filed here through the wasm door (`words_file`, the store's own `his_words`) under the keeper
/// of the chat holding the turn -- a Diamond's id, else `chat:<id>`, never a keeper the report
/// names. Filing is a merge that drops what the log holds, so a report heard again files
/// harmlessly. Answers whether the words are in the log (true when the report owes none).
export async function settleRunnerWords(report) {
	var words = report && typeof report.words === 'string' ? report.words : '';
	if (!words) return true;
	var chat = chatHoldingTurn(report.turnId);
	var said = 'turn=' + String(report.turnId || '');
	if (!chat) {
		diag('runner words', said + ' not filed: no chat here holds the turn');
		return false;
	}
	var keeper = chat.diamondId ? String(chat.diamondId) : 'chat:' + String(chat.id || '');
	said = 'chat=' + String(chat.id || '').slice(0, 12) + ' ' + said;
	try {
		await Wasm.words_file(keeper, words);
		return true;
	} catch (e) {
		diag('runner words', said + ' not filed: ' + String((e && e.message) || e)
			+ '; the session is not stored, and the transcript holds his words');
		return false;
	}
}

/// A RUNNER'S ALERTS COME HOME (KT-5d): a Diamond's turn on a runner raised or cleared alerts
/// with no page to put them on, and its `report` carries each. They go on this tab's Pending
/// panel through the engine's own door (`DaimondPendingTool`), in order, under the Diamond of
/// the chat holding the turn (`chatHoldingReport`, loaded on demand) -- never a Diamond the
/// report names. Each is stamped by the turn's own time, the report's `ts` plus its place, so
/// a report applied again can never outrank a take-down made since; and applied is kept per
/// errand on this device (`DaimondAlerts.hear`), across a reload (QA ccp4-b K2). Answers how
/// many the panel took.
export async function settleRunnerAlerts(report) {
	var list = report && Array.isArray(report.alerts) ? report.alerts : [];
	var A = window.DaimondAlerts;
	if (!list.length || !window.DaimondPendingTool || !A) return 0;
	var eid = String(report.eid || '');
	if (!eid || A.heard(eid)) return 0;
	var chat = await chatHoldingReport(report);
	if (!chat || !chat.diamondId) {
		diag('runner alerts', 'eid=' + eid.slice(0, 12) + ' ' + list.length + ' not applied: no chat here holds turn '
			+ String(report.turnId || '').slice(0, 12) + (chat ? ' in a Diamond' : ''));
		return 0;
	}
	if (A.heard(eid)) return 0;		// applied while the chat loaded
	var ts = Number(report.ts) > 0 ? Math.floor(Number(report.ts)) : 0;
	var took = 0;
	list.forEach(function (a, i) {
		var op = a && a.op;
		if (op !== 'raise' && op !== 'clear') return;
		var rest = op === 'raise' ? { key: a.key, headline: a.headline, detail: a.detail, needs: a.needs } : { key: a.key };
		var said = {};
		try { said = JSON.parse(window.DaimondPendingTool[op](chat.diamondId, JSON.stringify(rest), ts ? ts + i : 0)) || {}; }
		catch (e) { said = {}; }
		if (said.ok) took++;
		else diag('runner alert', 'chat=' + String(chat.id || '').slice(0, 12) + ' ' + op + ' ' + String(a.key || '')
			+ ' not taken: ' + String(said.reason || 'no answer'));
	});
	A.hear(eid);
	return took;
}

/// A runner's question, in the shape the Decision tile draws (`renderAsk`), or null where the
/// tile cannot draw it. Only the tile's own fields are kept, each as a string: an option's
/// `means` is the contract's word, an older `description` standing for it, and an `app` mark is never
/// taken, so a model's question can never pass for the engine's own blocked Decision.
function runnerAskArgs(p) {
	if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
	var str = function (s) { return typeof s === 'string' ? s : ''; };
	var o = {
		question:  str(p.question),
		options:   (Array.isArray(p.options) ? p.options : []).map(function (op) {
			op = op && typeof op === 'object' ? op : {};
			var c = { label: str(op.label), means: str(op.means) || str(op.description) };
			if (op.recommended === true) c.recommended = true;
			return c;
		}),
		recommend: str(p.recommend),
		why:       str(p.why),
		if_silent: str(p.if_silent),
	};
	if (Number(p.n) > 0 && Number(p.of) >= Number(p.n)) { o.n = Math.floor(Number(p.n)); o.of = Math.floor(Number(p.of)); }
	return askDrawable(o) ? o : null;
}

/// A RUNNER'S QUESTION COMES HOME AS BUTTONS (RUNNER-ASK, UNBLOCK-38): a turn on a runner that
/// put him a choice ends with `report.ask`. It is stored in the chat holding the turn
/// (`chatHoldingReport`, K2's rule) as the Ask row a local `ask` call leaves, so the existing
/// Decision tile draws it, inline at the end of the turn, and a reload draws it again from the
/// transcript. Its mid is the errand's, so the report heard again, here or on another device,
/// stores nothing more. The tile writes the model's words as text, never HTML (`renderAsk`), and
/// his pick goes as his next message through the one send entry, on the seat drawn at the press
/// (`askAnswer` -> `sendUserMessage`). Answers whether a row was stored.
export async function settleRunnerAsk(report) {
	var o = runnerAskArgs(report && report.ask);
	if (!o || !window.DaimondPeer || !window.DaimondPeer.settlingReport(report)) return false;
	var eid = String(report.eid || ''), tid = String(report.turnId || '');
	if (!eid || !tid) return false;
	// ONE ROW ID, ONE CARD: the runner names the frame's own Ask row (`report.ask.row`, as its
	// turn rows write it, `<run>-t<i>`), and the row is stored under that id, so the frame's copy
	// and this one are the same row whichever lands first. A report without it falls back to
	// the errand's id and the question match below.
	var named = report.ask && typeof report.ask.row === 'string' && /^[A-Za-z0-9_.:-]{1,160}$/.test(report.ask.row)
		? report.ask.row : '';
	var mid = named || 'ask-' + eid;
	if (loadMsgTombs()[mid]) return false;		// deleted here
	var chat = await chatHoldingReport(report);
	if (!chat || !Array.isArray(chat.messages)) {
		diag('runner ask', 'eid=' + eid.slice(0, 12) + ' not drawn: no chat here holds turn ' + tid.slice(0, 12));
		return false;
	}
	// ONE ASK ROW PER QUESTION (QA MED2): the runner's final frame carries the question as the
	// done Ask row its run wrote, so the report's copy is only the fallback for a frame that
	// held none; a second row would draw a second tile for the one question.
	for (var i = 0; i < chat.messages.length; i++) {
		var m = chat.messages[i];
		if (!m) continue;
		if (m.mid === mid) return false;
		if (!named && m.role === 'tool_log' && m.name === 'ask' && m.outcome === 'done' && String(m.iturn || '') === tid) {
			var had = null;
			try { had = runnerAskArgs(JSON.parse(m.args)); } catch (e) { had = null; }
			if (had && had.question === o.question) return false;
		}
	}
	var ts = Number(report.ts) > 0 ? Math.floor(Number(report.ts)) : Date.now();
	chat.messages.push(touchMsg({ role: 'tool_log', mid: mid, iturn: tid, name: 'ask', args: JSON.stringify(o),
		content: '', outcome: 'done', ts: ts }));
	touchChat(chat);
	persistChats();
	if (ownsChat(chat)) renderHistory(chat.messages);
	return true;
}

/// A runner's turn has settled in `chat`, so its engine, which holds the conversation from
/// before that turn, is stale. Dropped now, its taint verdict kept first (H3), or, while a
/// turn or a fold holds it, marked so that the next build (`ensureApp`) drops it, as
/// `_scopeStale` is honoured at a turn's start. A Diamond's daimon is laid per turn from
/// its record (`daimonPrior`) and is not touched.
function staleEngine(chat) {
	if (!chat || chat.diamondId || !chat.app) return;
	if (chat._generating || chat.app.busy) { chat._engineStale = true; return; }
	keepChatTaint(chat, chat.app);
	chat.app = null; chat._held = null; chat._engineStale = false;
}

/// Cut the stored session back to before the first of `rows` it holds, which are about to leave the transcript.
///
/// The session is a cache of the transcript in the model's own form and carries no message ids, so it is cut where
/// the retracted turn's prompt begins (`marks`, written by `captureSession`). What stands before that point -- the
/// fold, earlier turns' tool-call ids -- is kept, and the marker moves to the row before that prompt, so whatever
/// of the transcript remains after it is laid on as prose. Where the turn has no mark (folded, or a session stored by
/// an older build) the session goes to the cleared form and the next engine is laid from the transcript alone:
/// emptied rather than nulled, so a stored copy's `!c.session` fill-in does not bring it back. A row only in its tail
/// it never held, so it is kept. Called before the rows are filtered out, since both are found by position.
export function sessionCut(chat, rows) {
	var sess = chat && chat.session;
	if (!sess || !Array.isArray(sess.msgs) || !sess.msgs.length || !rows || !rows.length) return false;
	// What the engine may hold is everything up to the marker, by position: an answer an older build laid on without
	// its prompt (check_fix4 G1) stands above the marker, and the id rule of `tailAfter` would call it unheard.
	var tail = {};
	tailAfter(chat, { upto: sess.upto, uptoTs: sess.uptoTs }).forEach(function (m) { tail[String(m.mid)] = 1; });
	var held = rows.filter(function (m) {
		return m && m.content && (m.role === 'user' || m.role === 'assistant') && tail[String(m.mid)] !== 1;
	});
	if (!held.length) return false;
	// The cut stands at the earliest prompt among the held rows' turns. A row's turn is its tag's (`iturn`, the rule
	// `turnSpan` keeps), so a turn's answer that landed below a queued prompt is still its own turn's (check_fix3
	// F3). An untagged row, from a build before every row was tagged, has no turn by id: the nearest prompt above it
	// is a guess that a queued prompt makes wrong (check_fix5 H1), so it finds none, and the session is laid again
	// from the transcript.
	var all = chat.messages || [], marks = sess.marks || {}, cut = sess.msgs.length, from = all.length;
	var promptOf = function (m) {
		if (m.role === 'user') return all.indexOf(m);
		var t = String(m.iturn || '');
		for (var p = 0; t && p < all.length; p++) {
			var q = all[p];
			if (q && q.role === 'user' && (String(q.mid || '') === t || String(q.iturn || '') === t)) return p;
		}
		return -1;
	};
	// A mark is good only while it stands on its own prompt's entry: anything else (a stale index) is no mark.
	var marked = function (mid) {
		var at = marks[mid];
		return (typeof at === 'number' && at >= 0 && at < sess.msgs.length && sess.msgs[at]
			&& sess.msgs[at].role === 'user' && String(sess.msgs[at].mid || '') === mid) ? at : -1;
	};
	// Is every user entry from the first marked one on carried by id? Then a turn after a marked one that has no mark
	// is a turn the engine never heard (a queued prompt that landed before the running turn's answer), and there is
	// nothing of it to cut.
	var first = -1, whole = true;
	for (var e = 0; e < sess.msgs.length; e++) {
		var x = sess.msgs[e];
		if (!x || x.role !== 'user') continue;
		if (x.mid && first < 0 && marked(String(x.mid)) === e) first = e;
		if (first >= 0 && !x.mid) { whole = false; break; }
	}
	var firstAt = -1;	// the transcript place of the first marked turn's prompt
	if (first >= 0) {
		var fm = String(sess.msgs[first].mid);
		for (var f = 0; f < all.length; f++) if (all[f] && all[f].role === 'user' && String(all[f].mid || '') === fm) { firstAt = f; break; }
	}
	held.forEach(function (m) {
		var i = promptOf(m);
		var at = i >= 0 ? marked(String(all[i].mid || '')) : -1;
		if (at < 0) {
			var id = i >= 0 ? String(all[i].mid || '') : '';
			if (m.role === 'user' && id && whole && firstAt >= 0 && i > firstAt && !sess.msgs.some(function (x) {
				return x && x.role === 'user' && String(x.mid || '') === id;
			})) return;	// a prompt this engine never heard; a held answer of its turn is still cut (check_fix4 G1)
			cut = -1; return;
		}
		if (cut >= 0 && at < cut) { cut = at; from = i; }
	});
	if (cut === sess.msgs.length) return false;	// nothing held was the engine's
	// The new marker: the last row before the cut prompt that the list accounts for, as `captureSession` picks one.
	var b = from - 1;
	while (b >= 0 && !(all[b] && all[b].content && (all[b].role === 'user' || all[b].role === 'assistant')
		&& !(all[b].role === 'assistant' && all[b].interrupted))) b--;
	var prev = b >= 0 ? all[b] : null;
	var keep = (cut > 0 && prev) ? sess.msgs.slice(0, cut) : [];	// no row to stand on: the tail would be the whole chat
	if (!keep.length) {
		chat.session = { v: 1, msgs: [], upto: '', uptoTs: 0, marks: {} };
		diag('session cut', 'chat=' + String(chat.id || '').slice(0, 12) + ' it held ' + held.length
			+ ' retracted row(s) ' + (cut < 0 ? 'with no mark' : 'from its start') + '; the engine is laid from the transcript');
		return true;
	}
	var left = {};
	Object.keys(marks).forEach(function (k) { if (marks[k] < cut) left[k] = marks[k]; });
	chat.session = { v: 1, msgs: keep, upto: prev.mid || '', uptoTs: prev.ts || 0, marks: left };
	// What it held up to the new marker, still held (QA ccp2 M2).
	if (sess.held && typeof sess.held === 'object') {
		var kept = {};
		for (var h = 0; h <= b; h++) if (all[h] && all[h].mid && sess.held[String(all[h].mid)] === 1) kept[String(all[h].mid)] = 1;
		chat.session.held = kept;
	}
	diag('session cut', 'chat=' + String(chat.id || '').slice(0, 12) + ' it held ' + held.length
		+ ' retracted row(s); kept ' + cut + ' of ' + sess.msgs.length + ' model message(s)');
	return true;
}

/// Take the rows an errand names as removed by its sender (`gone`) out of this copy of the chat, under the same
/// tombstone the parcel will bring.
export function honourGone(chat, errand) {
	var goneIds = Array.isArray(errand.gone) ? errand.gone.map(String) : [];
	if (!goneIds.length) return;
	var goneHere = (chat.messages || []).filter(function (m) { return m && m.mid && goneIds.indexOf(String(m.mid)) >= 0; });
	if (!goneHere.length) return;
	try { msgTombstone(goneHere.map(function (m) { return m.mid; })); } catch (e) { /* the filter still stands here */ }
	sessionCut(chat, goneHere);
	chat.messages = chat.messages.filter(function (m) { return goneHere.indexOf(m) === -1; });
	chat.app = null;			// rebuilt from the transcript it now holds
	touchChat(chat); persistChats();
	diag('reconstruct gone', 'chat=' + chat.id + ' turn=' + errand.turnId
		+ ' removed ' + goneHere.length + ' row(s) the sender retracted');
}

/// The screen messages a stored session does not already account for.
///
/// By position while the marker is still in the transcript, and by timestamp when it
/// is not — a message can be tombstoned out from under the marker (continuing an
/// interrupted turn does exactly that), and falling back to the clock is what stops
/// the tail from replaying the whole conversation a second time. Above the marker, a
/// turn whose prompt the stored list does not hold by id is in the tail too.
/// Why a stored session cannot be laid with `tail` (`tailAfter`) behind it, or '' when it
/// can. 'early': a turn it never heard stands before one it holds, and the model's history
/// cannot be inserted into (check_fix5 L1). 'lost': an untagged answer (an old-build peer's)
/// stands after a prompt the tail lays on by id, above the marker, so the tail would drop it
/// and the model would read that prompt with no answer (check_fix6 M1). 'lacks': an answer the engine never took
/// (not in `held`) stands above the marker with its prompt held (QA ccp1 M1, ccp2 M2), so laid behind it would follow a
/// later turn. Every way the
/// engine is laid from the transcript. `exceptMid` is the prompt about to be re-sent.
export function sessionDoubt(chat, sess, tail, exceptMid) {
	var msgs = chat.messages || [];
	var lastHeld = -1, ids = {};
	sess.msgs.forEach(function (x) { if (x && x.role === 'user' && x.mid) ids[String(x.mid)] = 1; });
	msgs.forEach(function (m, n) { if (m && m.role === 'user' && ids[String(m.mid || '')] === 1) lastHeld = n; });
	var early = tail.some(function (m) {
		return m.role === 'user' && (!exceptMid || String(m.mid) !== String(exceptMid)) && msgs.indexOf(m) < lastHeld;
	});
	if (early) return 'early';
	// An answer the engine never took stands above the marker, its prompt held (QA ccp1 M1, ccp2 M2):
	// laid behind the session it would follow a later turn, so the engine is laid from the transcript.
	if (sess.held && typeof sess.held === 'object') {
		var mark = -1;
		for (var u = 0; u < msgs.length; u++) if (msgs[u] && sess.upto && msgs[u].mid === sess.upto) { mark = u; break; }
		var prompts = {};
		tail.forEach(function (m) { if (m.role === 'user' && m.mid) prompts[String(m.mid)] = 1; });
		var orphan = tail.some(function (m) {
			var n = msgs.indexOf(m);
			var above = mark >= 0 ? n < mark : (m.ts || 0) <= (Number(sess.uptoTs) || 0);
			return above && m.role === 'assistant' && prompts[String(m.iturn || '')] !== 1;
		});
		if (orphan) return 'lacks';
	}
	var inTail = new Set(tail), byId = -1, lost = false;
	msgs.forEach(function (m, n) {
		if (lost || !m) return;
		if (m.role === 'user') {
			if (inTail.has(m) && (!exceptMid || String(m.mid) !== String(exceptMid))) byId = n;
			return;
		}
		lost = byId >= 0 && m.role === 'assistant' && m.content && !m.iturn && !m.provisional
			&& !inTail.has(m) && m.mid !== sess.upto;
	});
	return lost ? 'lost' : '';
}

/// The transcript row a stored session's marker (`upto`, `uptoTs`) stands on: the last
